1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { canAdministerOrg, verifyInviteToken } from "@/lib/team-guard";
5	import { PageHeader } from "@/components/ui/primitives";
6	import TeamInviteAccept from "@/components/customer/TeamInviteAccept";
7	
8	export const dynamic = "force-dynamic";
9	
10	/**
11	 * Landing page for the "Accept invitation" link in the team-invite email.
12	 *
13	 * This page only DESCRIBES the invitation — it never joins anyone. Joining
14	 * happens in `acceptInvite`, behind a button the invitee presses. That split is
15	 * the point of the whole change: an org membership must be an act by the
16	 * invitee, not a side effect of an email link being opened (or prefetched by a
17	 * mail client). Previously `inviteMember` created the membership on the
18	 * inviter's click alone.
19	 *
20	 * Signed-out visitors are bounced to /login by the dashboard layout. Someone
21	 * without an account yet registers first and then re-opens the emailed link;
22	 * the link stays valid for its full lifetime, so nothing is lost.
23	 */
24	export default async function AcceptInvitePage({
25	  searchParams,
26	}: {
27	  searchParams: Promise<{ token?: string }>;
28	}) {
29	  const user = await requireUser();
30	  const { token } = await searchParams;
31	
32	  const claims = await verifyInviteToken(String(token ?? ""));
33	
34	  // Everything below decides only what to SHOW. Each check is repeated
35	  // server-side in `acceptInvite`, because a page render is not a permission.
36	  let problem: string | null = null;
37	  let orgName: string | null = null;
38	  let inviterName: string | null = null;
39	
40	  if (!claims) {
41	    problem = "This invitation link is invalid or has expired. Ask the organization owner to send a new one.";
42	  } else if (claims.email !== user.email.trim().toLowerCase()) {
43	    // Don't name the org here: the signed-in account isn't the invitee, so it
44	    // isn't entitled to know which organization the link belongs to.
45	    problem = `This invitation was sent to a different email address. You're signed in as ${user.email} — sign in as the invited account to accept it.`;
46	  } else {
47	    const org = await db.organization.findUnique({
48	      where: { id: claims.orgId },
49	      select: { id: true, name: true },
50	    });
51	    const inviter = org
52	      ? await db.membership.findUnique({
53	          where: { orgId_userId: { orgId: org.id, userId: claims.invitedBy } },
54	          include: { user: { select: { name: true } } },
55	        })
56	      : null;
57	    if (!org) {
58	      problem = "That organization no longer exists.";
59	    } else if (!inviter || !canAdministerOrg(inviter.role)) {
60	      problem = "Whoever invited you no longer administers this organization, so the invitation is no longer valid.";
61	    } else {
62	      orgName = org.name;
63	      inviterName = inviter.user.name;
64	    }
65	  }
66	
67	  return (
68	    <div className="space-y-6">
69	      <PageHeader title="Team invitation" sub="Review the invitation before you join." />
70	      {problem || !claims || !orgName ? (
71	        <div className="card space-y-3">
72	          <p className="text-sm text-red-400">{problem ?? "This invitation can't be opened."}</p>
73	          <Link href="/dashboard/team" className="btn-ghost inline-flex px-3 py-1 text-xs">
74	            Back to Team
75	          </Link>
76	        </div>
77	      ) : (
78	        <TeamInviteAccept
79	          token={String(token)}
80	          orgName={orgName}
81	          inviterName={inviterName ?? "An organization admin"}
82	          role={claims.role}
83	        />
84	      )}
85	    </div>
86	  );
87	}
