20	function shortKey(publicKey: string): string {
21	  const parts = publicKey.trim().split(/\s+/);
22	  const body = parts[1] ?? parts[0] ?? "";
23	  const type = parts[0] ?? "";
24	  if (body.length <= 40) return publicKey;
25	  return `${type} ${body.slice(0, 24)}…${body.slice(-12)}`;
26	}
