61	      </div>
62	
63	      <div className="card">
64	        <h2 className="mb-4 font-semibold">Password</h2>
65	        <PasswordForm />
66	      </div>
67	
68	      <div className="card">
69	        <div className="mb-1 flex items-center justify-between">
70	          <h2 className="font-semibold">SSH keys</h2>
71	          <span className="text-xs text-slate-500">
72	            {sshKeys.length} key{sshKeys.length === 1 ? "" : "s"}
73	          </span>
74	        </div>
75	        <p className="mb-5 text-sm text-slate-400">
76	          Keys are injected into new servers automatically at deploy time.
77	        </p>
78	
79	        {sshKeys.length > 0 && (
80	          <ul className="mb-6 divide-y divide-white/[0.05] rounded-xl border border-white/[0.06]">
81	            {sshKeys.map((k) => (
82	              <li key={k.id} className="flex items-center justify-between gap-4 px-4 py-3">
