86	                </div>
87	                <div className="flex shrink-0 items-center gap-3">
88	                  <span className="hidden text-xs text-slate-500 sm:block">
89	                    added {timeAgo(k.createdAt)}
90	                  </span>
91	                  <DeleteSshKeyButton keyId={k.id} />
92	                </div>
93	              </li>
94	            ))}
95	          </ul>
