83	export function ReplyForm({ ticketId }: { ticketId: string }) {
84	  const [state, action, pending] = useActionState(replyTicket, {});
85	  const [body, setBody] = useState("");
86	  // A reply has two outcomes and they want OPPOSITE things from the field, which
87	  // is why simply making it controlled is not enough:
88	  //   - rejected  → keep every character; React 19 would otherwise blank up to
89	  //                 10,000 of them on the form-action submit, and the customer
90	  //                 will not retype them.
91	  //   - accepted  → clear it, or the sent reply sits there looking unsent and
92	  //                 gets sent twice.
93	  // So the field is controlled and cleared only on a submit that came back
94	  // without an error, watching the pending edge rather than the state shape
95	  // (the action returns `{}` for success, which is indistinguishable from its
96	  // initial value).
97	  const wasPending = useRef(false);
98	  useEffect(() => {
99	    if (wasPending.current && !pending && !state?.error) setBody("");
100	    wasPending.current = pending;
101	  }, [pending, state]);
102	  return (
103	    <form action={action} className="space-y-3">
104	      <input type="hidden" name="ticketId" value={ticketId} />
105	      {state?.error && <p className="text-sm text-red-400">{state.error}</p>}
106	      <textarea
107	        className="input min-h-28 resize-y"
108	        name="body"
109	        required
110	        minLength={2}
111	        maxLength={10000}
112	        value={body}
113	        onChange={(e) => setBody(e.target.value)}
114	        placeholder="Write a reply…"
115	      />
116	      <div className="flex justify-end">
117	        <button className="btn-primary px-6" disabled={pending}>
118	          {pending ? "Sending…" : "Send reply"}
119	        </button>
120	      </div>
121	    </form>
122	  );
123	}
124	
125	export function TicketStatusButton({ ticketId, status }: { ticketId: string; status: string }) {
126	  const [pending, start] = useTransition();
127	  const closed = status === "CLOSED";
128	  return (
129	    <button
130	      className={closed ? "btn-secondary" : "btn-danger"}
131	      disabled={pending}
132	      onClick={() => start(() => setTicketStatus(ticketId, closed ? "OPEN" : "CLOSED"))}
133	    >
134	      {pending ? "…" : closed ? "Reopen ticket" : "Close ticket"}
135	    </button>
136	  );
137	}
