57	export function AddSshKeyForm() {
58	  const [state, action, pending] = useActionState(addSshKey, {});
59	  // CONTROLLED, deliberately — the same reason components/customer/TicketForms.tsx
60	  // is. React 19 resets uncontrolled fields on every `<form action={fn}>` submit,
61	  // and the one error this form can return is
62	  // `"Not a valid OpenSSH public key"` (lib/actions-account.ts:54). So the field
63	  // was blanked at precisely the moment the customer needs the text back: a
64	  // multi-line key they pasted out of a terminal, rejected, gone. They then have
65	  // to go and `cat ~/.ssh/id_ed25519.pub` again to fix a typo they can no longer
66	  // see. Cleared only on a submit that came back without an error, watching the
67	  // pending edge because the action returns `{}` for success — indistinguishable
68	  // from its initial value.
69	  const [name, setName] = useState("");
70	  const [publicKey, setPublicKey] = useState("");
71	  const wasPending = useRef(false);
72	  useEffect(() => {
73	    if (wasPending.current && !pending && !state?.error) {
74	      setName("");
75	      setPublicKey("");
76	    }
77	    wasPending.current = pending;
78	  }, [pending, state]);
79	
80	  return (
81	    <form action={action} className="space-y-4">
82	      {state?.error && <p className="text-sm text-red-400">{state.error}</p>}
83	      <div className="max-w-xs">
84	        <label className="label" htmlFor="ssh-key-name">
85	          Key name
86	        </label>
87	        <input
88	          id="ssh-key-name"
89	          className="input"
90	          name="name"
91	          required
92	          maxLength={60}
93	          placeholder="work-laptop"
94	          value={name}
95	          onChange={(e) => setName(e.target.value)}
96	        />
97	      </div>
98	      <div>
99	        <label className="label" htmlFor="ssh-key-body">
100	          Public key
101	        </label>
102	        <textarea
103	          id="ssh-key-body"
104	          className="input min-h-24 resize-y font-mono text-xs"
105	          name="publicKey"
106	          required
107	          placeholder="ssh-ed25519 AAAAC3NzaC1lZDI1NTE5… user@host"
108	          value={publicKey}
109	          onChange={(e) => setPublicKey(e.target.value)}
110	        />
111	        <p className="mt-1 text-xs text-slate-500">
112	          The contents of <code className="font-mono text-brand-200">~/.ssh/id_ed25519.pub</code> —
113	          the public half, one line, starting <code className="font-mono text-brand-200">ssh-</code>.
114	          Never paste a private key.
115	        </p>
116	      </div>
117	      <button className="btn-primary" disabled={pending}>
118	        {pending ? "Adding…" : "Add SSH key"}
119	      </button>
120	    </form>
121	  );
122	}
123	
124	export function DeleteSshKeyButton({ keyId }: { keyId: string }) {
125	  const [pending, start] = useTransition();
126	  return (
127	    <button
128	      className="btn-danger px-3 py-1 text-xs"
129	      disabled={pending}
130	      onClick={() => {
131	        if (window.confirm("Delete this SSH key? It will no longer be injected into new servers."))
132	          start(() => deleteSshKey(keyId));
133	      }}
134	    >
135	      {pending ? "…" : "Delete"}
136	    </button>
137	  );
138	}
