9	async function ensureReferralCode(userId: string, current: string | null): Promise<string> {
10	  if (current) return current;
11	  for (let i = 0; i < 6; i++) {
12	    const code = generateReferralCode();
13	    const clash = await db.user.findUnique({ where: { referralCode: code } });
14	    if (clash) continue;
15	    try {
16	      await db.user.update({ where: { id: userId }, data: { referralCode: code } });
17	      return code;
18	    } catch {
19	      /* unique clash race — retry */
20	    }
21	  }
22	  const fallback = generateReferralCode(12);
23	  await db.user.update({ where: { id: userId }, data: { referralCode: fallback } });
24	  return fallback;
25	}
26	
