1460	 * wrong DNS record, because nothing here writes anything.
1461	 */
1462	const MULTI_LABEL_SUFFIXES = [
1463	  "co.uk", "org.uk", "ac.uk", "gov.uk", "me.uk", "com.au", "net.au", "org.au",
1464	  "co.nz", "com.br", "com.mx", "com.ar", "co.za", "co.in", "co.jp", "com.sg",
1465	  "com.tr", "com.pl", "com.ua", "co.il", "co.kr", "com.cn", "com.hk", "com.tw",
