1468	/** Best-effort registrable zone for a hostname (`app.example.co.uk` → `example.co.uk`). */
1469	function zoneGuess(host: string): string {
1470	  const labels = host.split(".").filter(Boolean);
1471	  if (labels.length <= 2) return labels.join(".");
1472	  const lastTwo = labels.slice(-2).join(".");
1473	  return MULTI_LABEL_SUFFIXES.includes(lastTwo) ? labels.slice(-3).join(".") : lastTwo;
1474	}
