1476	/** One click straight to a zone's DNS records in Cloudflare's dashboard. */
1477	function cloudflareDnsUrl(host: string): string {
1478	  // `:account` is Cloudflare's own placeholder — their dashboard substitutes the
1479	  // signed-in account, so this works without us knowing the account id.
1480	  return `https://dash.cloudflare.com/?to=/:account/${encodeURIComponent(zoneGuess(host))}/dns`;
1481	}
