1686	  const candidates = info?.candidates ?? [];
1687	  const targetIp = info?.targetIp ?? null;
1688	  // Return here (this exact migration) after a Cloudflare consent round trip.
1689	  const nextPath = `/dashboard/migrate?migration=${migrationId}`;
