1697	        {targetIp ? (
1698	          <span className="font-mono text-slate-200">{targetIp}</span>
1699	        ) : (
1700	          "your new server's IP"
1701	        )}{" "}
1702	        in your Cloudflare zone. Records are created{" "}
1703	        <span className="font-medium text-slate-200">DNS-only (no orange cloud)</span> so the name
