17	};
18	export type GameMeta = { family: string; name: string; glyph: string };
19	
20	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
21	const gb = (mb: number) => `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
22	
23	/**
24	 * Customer game-server deploy: pick a game, pick a tier, deploy. Charges the
25	 * tier's price from the wallet via orderGameServer (which redirects to the new
26	 * server on success).
27	 */
28	export function GameDeploy({
29	  games,
30	  tiers,
31	  balanceCents,
32	}: {
33	  games: GameMeta[];
34	  tiers: Tier[];
35	  balanceCents: number;
36	}) {
37	  const firstGame = games[0]?.family ?? "";
38	  const [game, setGame] = useState(firstGame);
39	  const [selected, setSelected] = useState<string | null>(null);
40	  const [error, setError] = useState<string | null>(null);
41	  const [pending, start] = useTransition();
42	
43	  const gameTiers = useMemo(
44	    () => tiers.filter((t) => t.gameFamily === game).sort((a, b) => a.priceCents - b.priceCents),
45	    [tiers, game],
46	  );
47	
48	  const chosen = gameTiers.find((t) => t.id === selected) ?? null;
49	  const insufficient = chosen ? balanceCents < chosen.priceCents : false;
50	
51	  function deploy() {
52	    if (!chosen) return;
53	    setError(null);
54	    start(async () => {
55	      const res = await orderGameServer(chosen.id);
56	      // On success orderGameServer redirects; only errors return here.
57	      if (res?.error) setError(res.error);
58	    });
59	  }
60	
61	  return (
62	    <div className="space-y-6">
63	      {/* Step 1 — game */}
64	      <div>
65	        <p className="label mb-2">1 · Choose a game</p>
66	        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6">
67	          {games.map((g) => {
68	            const active = g.family === game;
69	            const count = tiers.filter((t) => t.gameFamily === g.family).length;
70	            return (
71	              <button
72	                key={g.family}
73	                onClick={() => {
74	                  setGame(g.family);
75	                  setSelected(null);
76	                  setError(null);
77	                }}
78	                className={`card card-hover flex flex-col items-center gap-1.5 py-4 text-center transition ${
79	                  active ? "border-brand-400 ring-1 ring-brand-400/40" : ""
80	                }`}
81	              >
82	                <span className="text-2xl">{g.glyph}</span>
83	                <span className="text-sm font-medium text-white">{g.name}</span>
84	                <span className="text-[11px] text-slate-500">
85	                  {count} tier{count === 1 ? "" : "s"}
86	                </span>
87	              </button>
88	            );
89	          })}
90	        </div>
91	      </div>
92	
93	      {/* Step 2 — tier */}
94	      <div>
95	        <p className="label mb-2">2 · Choose a plan</p>
96	        {gameTiers.length === 0 ? (
97	          <p className="text-sm text-slate-500">No plans are available for this game yet. Check back soon.</p>
98	        ) : (
99	          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
100	            {gameTiers.map((t) => {
101	              const active = t.id === selected;
102	              return (
103	                <button
104	                  key={t.id}
105	                  onClick={() => {
106	                    setSelected(t.id);
107	                    setError(null);
108	                  }}
109	                  className={`card card-hover text-left transition ${
110	                    active ? "border-brand-400 ring-1 ring-brand-400/40" : ""
111	                  }`}
112	                >
113	                  <div className="flex items-center justify-between gap-2">
114	                    <span className="font-semibold text-white">{t.name}</span>
115	                    {t.featured && (
116	                      <span className="rounded-full border border-brand-500/40 bg-brand-500/10 px-2 py-0.5 text-[11px] text-brand-300">
117	                        Popular
118	                      </span>
119	                    )}
120	                  </div>
121	                  <p className="mt-2 text-2xl font-bold tracking-tight text-white">
122	                    {money(t.priceCents)}
123	                    <span className="text-sm font-normal text-slate-400">
124	                      {t.termMonths > 1 ? ` / ${t.termMonths} mo` : " / mo"}
125	                    </span>
126	                  </p>
127	                  <ul className="mt-3 space-y-1 text-sm text-slate-400">
128	                    <li>{gb(t.ramMB)} RAM · {t.cpuCores} vCPU</li>
129	                    <li>{t.diskGB} GB NVMe disk</li>
130	                    {t.slots != null && <li>Up to {t.slots} player slots</li>}
131	                  </ul>
132	                </button>
133	              );
134	            })}
135	          </div>
136	        )}
137	      </div>
138	
139	      {/* Step 3 — deploy */}
140	      {chosen && (
141	        <div className="card flex flex-wrap items-center justify-between gap-4">
142	          <div>
143	            <p className="text-sm text-slate-400">
144	              Deploying <span className="font-medium text-white">{chosen.name}</span>. You&apos;ll be charged{" "}
145	              <span className="font-medium text-white">{money(chosen.priceCents)}</span> from your wallet
146	              (balance {money(balanceCents)}).
147	            </p>
148	            {error && <p className="mt-1 text-sm text-red-400">{error}</p>}
149	            {insufficient && !error && (
150	              <p className="mt-1 text-sm text-amber-400">Insufficient balance — top up your wallet first.</p>
151	            )}
152	          </div>
153	          <button className="btn-primary" disabled={pending || insufficient} onClick={deploy}>
154	            {pending ? "Deploying…" : "Deploy server"}
155	          </button>
156	        </div>
157	      )}
158	    </div>
159	  );
160	}
