166	          disabled={disabled}
167	          onClick={() => onChange(!on)}
168	          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
169	            on ? "bg-brand-500" : "bg-white/15"
170	          } ${disabled ? "opacity-60" : ""}`}
171	        >
172	          <span
173	            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
174	              on ? "translate-x-5" : "translate-x-0.5"
