182	  return (
183	    <label className="block text-sm">
184	      {labelRow}
185	      {field.type === "enum" ? (
186	        <select
187	          className="input"
188	          value={String(value ?? field.default)}
189	          disabled={disabled}
190	          onChange={(e) => onChange(e.target.value)}
191	        >
192	          {field.options?.map((o) => (
193	            <option key={o.value} value={o.value}>
194	              {o.label}
195	            </option>
196	          ))}
197	        </select>
198	      ) : field.type === "int" ? (
199	        <input
200	          className="input"
201	          type="number"
202	          value={value === undefined || value === null ? Number(field.default) : Number(value)}
203	          min={field.min}
204	          max={field.max}
205	          step={1}
206	          disabled={disabled}
207	          onChange={(e) => onChange(e.target.value === "" ? "" as any : Number(e.target.value))}
208	        />
209	      ) : (
210	        <input
211	          className="input"
212	          type="text"
213	          value={String(value ?? field.default)}
214	          maxLength={256}
215	          disabled={disabled}
216	          onChange={(e) => onChange(e.target.value)}
217	        />
218	      )}
219	      {field.help && (
220	        <span className="mt-1 block text-xs text-slate-500">{field.help}</span>
221	      )}
222	    </label>
223	  );
224	}
