1	"use client";
2	
3	import { useEffect, useState, useTransition } from "react";
4	import Link from "next/link";
5	import { dismissOnboarding } from "@/lib/actions-onboarding";
6	
7	/**
8	 * "Getting started" checklist for new customers, mounted on the dashboard by
9	 * the orchestrator: `<OnboardingChecklist steps={await getOnboardingSteps()} />`.
10	 *
11	 * Steps are computed server-side (see lib/actions-onboarding.ts) and passed in.
12	 * The card:
13	 *   - hides itself once every step is complete,
14	 *   - hides once dismissed (persisted in the `nxeon_onboarding_done` cookie,
15	 *     read client-side on mount and written both here and by the server action),
16	 *   - renders nothing until mounted to avoid a hydration flash.
17	 */
18	
19	export const ONBOARDING_COOKIE = "nxeon_onboarding_done";
20	
21	export type OnboardingStep = {
22	  key: "server" | "funds" | "twofa" | "domain";
23	  label: string;
24	  desc: string;
25	  done: boolean;
26	  href: string;
27	  cta: string;
28	};
29	
30	function isDismissed(): boolean {
31	  if (typeof document === "undefined") return true;
32	  return document.cookie.split("; ").some((c) => c.startsWith(`${ONBOARDING_COOKIE}=`));
33	}
34	
35	export default function OnboardingChecklist({ steps }: { steps: OnboardingStep[] }) {
36	  const [hidden, setHidden] = useState(true);
37	  const [pending, startTransition] = useTransition();
38	
39	  useEffect(() => {
40	    setHidden(isDismissed());
41	  }, []);
42	
43	  const doneCount = steps.filter((s) => s.done).length;
44	  const allDone = doneCount === steps.length;
45	
46	  // Nothing to show: dismissed, or the customer has finished every step.
47	  if (hidden || allDone || steps.length === 0) return null;
48	
49	  function dismiss() {
50	    // Hide instantly and persist client-side; also fire the server action so
51	    // the choice survives even if this cookie is later cleared client-side.
52	    try {
53	      document.cookie = `${ONBOARDING_COOKIE}=1; path=/; max-age=${60 * 60 * 24 * 365}; SameSite=Lax`;
54	    } catch {
55	      /* non-fatal */
56	    }
57	    setHidden(true);
58	    startTransition(() => {
59	      void dismissOnboarding().catch(() => {});
60	    });
61	  }
62	
63	  const pct = Math.round((doneCount / steps.length) * 100);
64	  const next = steps.find((s) => !s.done);
65	
66	  return (
67	    <div className="card relative overflow-hidden">
68	      <div
69	        className="pointer-events-none absolute inset-0 opacity-60"
70	        style={{
71	          backgroundImage:
72	            "radial-gradient(ellipse 50% 80% at 100% 0%, rgba(138,112,251,0.12), transparent)",
73	        }}
74	      />
75	      <div className="relative">
76	        <div className="flex items-start justify-between gap-4">
77	          <div>
78	            <h2 className="text-base font-semibold text-white">Getting started</h2>
79	            <p className="mt-1 text-[13px] text-slate-400">
80	              Finish setting up your account — {doneCount} of {steps.length} done.
81	            </p>
82	          </div>
83	          <button
84	            type="button"
85	            onClick={dismiss}
86	            disabled={pending}
87	            aria-label="Dismiss getting started checklist"
88	            className="btn-ghost -mr-1 -mt-1 shrink-0 px-2 py-1 text-xs text-slate-400 hover:text-white disabled:opacity-50"
89	          >
90	            Dismiss
91	          </button>
92	        </div>
93	
94	        {/* Progress bar */}
95	        <div className="mt-4 h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
96	          <div
97	            className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 transition-all duration-500"
98	            style={{ width: `${pct}%` }}
99	          />
100	        </div>
101	
102	        {/* Steps */}
103	        <ul className="mt-5 space-y-2">
104	          {steps.map((step) => {
105	            const isNext = next?.key === step.key;
106	            return (
107	              <li
108	                key={step.key}
109	                className={`flex items-center gap-3 rounded-xl border p-3 ${
110	                  step.done
111	                    ? "border-white/[0.06] bg-white/[0.02]"
112	                    : isNext
113	                      ? "border-brand-500/40 bg-brand-500/[0.06]"
114	                      : "border-white/[0.06]"
115	                }`}
116	              >
117	                <span
118	                  className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border ${
119	                    step.done
120	                      ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-400"
121	                      : "border-white/10 bg-white/[0.04] text-slate-500"
122	                  }`}
123	                  aria-hidden
124	                >
125	                  {step.done ? (
126	                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
127	                      <path d="M20 6 9 17l-5-5" />
128	                    </svg>
129	                  ) : (
130	                    <span className="h-1.5 w-1.5 rounded-full bg-current" />
131	                  )}
132	                </span>
133	                <div className="min-w-0 flex-1">
134	                  <p className={`text-sm font-medium ${step.done ? "text-slate-400 line-through" : "text-white"}`}>
135	                    {step.label}
136	                  </p>
137	                  {!step.done && <p className="text-[12px] text-slate-500">{step.desc}</p>}
138	                </div>
139	                {!step.done && (
140	                  <Link
141	                    href={step.href}
142	                    className={`shrink-0 px-3 py-1.5 text-xs ${isNext ? "btn-primary" : "btn-secondary"}`}
143	                  >
144	                    {step.cta}
145	                  </Link>
146	                )}
147	                {step.done && (
148	                  <span className="shrink-0 text-[11px] font-medium text-emerald-400">Done</span>
149	                )}
150	              </li>
151	            );
152	          })}
153	        </ul>
154	      </div>
155	    </div>
156	  );
157	}
