2	
3	const SCOPE_LABELS: Record<string, string> = {
4	  user: "Account",
5	  server: "Server",
6	  wallet: "Wallet",
7	  domain: "Domain",
8	  admin: "Admin",
9	};
10	
11	export function humanizeAction(action: string): string {
12	  const dot = action.indexOf(".");
13	  if (dot === -1) return action.replace(/_/g, " ");
14	  const scope = action.slice(0, dot);
15	  const verb = action.slice(dot + 1).replace(/_/g, " ");
16	  return `${SCOPE_LABELS[scope] ?? scope[0]?.toUpperCase() + scope.slice(1)} · ${verb}`;
17	}
18	
19	export function actionDotColor(action: string): string {
20	  if (action.includes("delete") || action.includes("suspend")) return "bg-red-400";
21	  if (action.startsWith("wallet") || action.includes("renew") || action.includes("topup")) return "bg-emerald-400";
22	  if (action.startsWith("domain")) return "bg-accent-cyan";
23	  if (action.startsWith("admin")) return "bg-amber-400";
24	  return "bg-brand-400";
25	}
