173	        <p className="section-label">Services</p>
174	        {running && (
175	          <button className="btn-ghost px-2 py-1 text-xs" onClick={() => void refresh()}>
176	            Refresh
177	          </button>
178	        )}
179	      </div>
180	      {error && <p className="px-4 pt-3 text-sm text-red-400">{error}</p>}
181	      {!running ? (
182	        <EmptyState title="Server not running" hint="Start the server to view and control services." />
