199	                  <td>
200	                    <span className="font-medium text-slate-100">{s.label}</span>
201	                    <span className="ml-2 font-mono text-[11px] text-slate-500">{s.unit}</span>
202	                  </td>
203	                  <td>
204	                    {s.state === "running" ? (
205	                      <span className="inline-flex items-center gap-1.5 text-emerald-300">
